insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'ruta-de-nomenclatura','chapter',$cbc$1. Ruta para reconocer, formular y nombrar$cbc$,10,$cbc$<p>Primero contá los <strong>elementos diferentes</strong>: dos, binario; tres, ternario; cuatro, cuaternario. Luego buscá grupos que no deben separarse: OH⁻, NH₄⁺, oxoaniones y sus formas con H.</p><div class="methodStep"><strong>1. Clasificá.</strong><p>¿Hay metal, oxígeno, hidrógeno, un no metal, OH⁻ o NH₄⁺? Identificá la familia antes de aplicar una terminación.</p></div><div class="methodStep"><strong>2. Asigná estados de oxidación.</strong><p>Elemento libre: 0; ion monoatómico: su carga; O: normalmente −2; H: +1 con no metales y −1 con metales; grupo 1: +1; grupo 2: +2. La suma vale 0 en sustancias neutras y la carga en iones.</p></div><div class="methodStep"><strong>3. Separá iones si corresponde.</strong><p>Escribí catión y anión completos, balanceá cargas y simplificá los subíndices. En compuestos covalentes distinguí fórmula molecular de unidad fórmula iónica.</p></div><div class="methodStep"><strong>4. Nombrá y verificá.</strong><p>El anión suele nombrarse antes que el catión. Indicá Stock cuando el elemento puede adoptar varios estados. Al final comprobá composición, carga y subíndices.</p></div><aside class="examTip"><strong>Ojo:</strong> número de oxidación, carga real y cantidad de átomos no son la misma cosa. El numeral de Stock indica estado de oxidación, no atomicidad.</aside>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'mapa-familias','chapter',$cbc$2. Mapa de las familias y sus elementos$cbc$,20,$cbc$<table><thead><tr><th>Familia</th><th>Elementos o iones</th><th>Ejemplo</th></tr></thead><tbody><tr><td>Óxido metálico</td><td>metal + O</td><td>Fe₂O₃</td></tr><tr><td>Óxido no metálico</td><td>no metal + O</td><td>SO₂</td></tr><tr><td>Hidruro metálico</td><td>metal + H⁻</td><td>CaH₂</td></tr><tr><td>Hidrácido / compuesto covalente de H</td><td>H + no metal, sin O</td><td>HCl(ac), CH₄</td></tr><tr><td>Sal binaria</td><td>metal + anión monoatómico</td><td>Cu₂S</td></tr><tr><td>Hidróxido</td><td>catión + OH⁻</td><td>Ni(OH)₃</td></tr><tr><td>Oxoácido</td><td>H + elemento central + O</td><td>H₂SO₃</td></tr><tr><td>Oxosal</td><td>catión + oxoanión</td><td>NaNO₂</td></tr><tr><td>Hidrogenosal</td><td>catión + hidrógenoanión</td><td>NaHS</td></tr><tr><td>Hidrógeno-oxosal</td><td>catión + hidrógeno-oxoanión</td><td>NaHCO₃</td></tr><tr><td>Sal de amonio</td><td>NH₄⁺ + anión</td><td>NH₄Cl</td></tr></tbody></table><p>Las sustancias simples tienen un solo elemento y estado de oxidación 0. Ejemplos: Fe, O₂, O₃; O₂ y O₃ son variedades alotrópicas. Otros compuestos binarios covalentes entre no metales se pueden nombrar con prefijos de atomicidad, por ejemplo PCl₅, pentacloruro de fósforo.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'numeros-de-oxidacion','chapter',$cbc$3. Números de oxidación y fórmula mínima$cbc$,30,$cbc$<p>En una sustancia neutra: suma de (subíndice × número de oxidación) = 0. En un ion: suma = carga. Si intercambiás valores absolutos de cargas para obtener subíndices, <strong>simplificá</strong> al final; nunca intercambies los signos.</p><p>Ca²⁺ + O²⁻ → Ca₂O₂ → CaO. K⁺ + O²⁻ → K₂O. Pb⁴⁺ + O²⁻ → Pb₂O₄ → PbO₂.</p><p>En un ion poliatómico conservá sus átomos y carga como unidad. Co²⁺ + 2 OH⁻ → Co(OH)₂; 2 Al³⁺ + 3 SO₄²⁻ → Al₂(SO₄)₃.</p><p>El O es −1 en peróxidos; el F suele ser −1. No apliques mecánicamente O = −2 a un peróxido, ni H = +1 a CaH₂.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'oxidos-metalicos','chapter',$cbc$4. Óxidos metálicos$cbc$,40,$cbc$<p>Metal + O²⁻. Son redes iónicas; su fórmula indica la menor relación de iones. Nombre: <strong>óxido de metal</strong>, con Stock si el metal tiene estados variables.</p><table><thead><tr><th>Fórmula</th><th>Nombre</th><th>Control</th></tr></thead><tbody><tr><td>Na₂O</td><td>óxido de sodio</td><td>2(+1) − 2 = 0</td></tr><tr><td>CaO</td><td>óxido de calcio</td><td>+2 − 2 = 0</td></tr><tr><td>Al₂O₃</td><td>óxido de aluminio</td><td>2(+3) + 3(−2) = 0</td></tr><tr><td>FeO / Fe₂O₃</td><td>óxido de hierro(II) / hierro(III)</td><td>Fe²⁺ / Fe³⁺</td></tr><tr><td>Cu₂O / CuO</td><td>óxido de cobre(I) / cobre(II)</td><td>Cu⁺ / Cu²⁺</td></tr></tbody></table><p><strong>Lewis iónico:</strong> mostrás por separado el catión y el anión [O]²⁻ con octeto; K₂O contiene 2 K⁺ y O²⁻, Al₂O₃ contiene 2 Al³⁺ y 3 O²⁻. No dibujes un enlace molecular K—O—K.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'oxidos-no-metalicos','chapter',$cbc$5. Óxidos no metálicos$cbc$,50,$cbc$<p>No metal + O. Predominan enlaces covalentes. Nombre Stock: óxido de elemento(número romano); también se usan prefijos mono-, di-, tri-, penta-, hepta- para indicar atomicidad.</p><table><thead><tr><th>Fórmula</th><th>Stock</th><th>Atomicidad</th></tr></thead><tbody><tr><td>Cl₂O</td><td>óxido de cloro(I)</td><td>monóxido de dicloro</td></tr><tr><td>SO₂</td><td>óxido de azufre(IV)</td><td>dióxido de azufre</td></tr><tr><td>SO₃</td><td>óxido de azufre(VI)</td><td>trióxido de azufre</td></tr><tr><td>N₂O₅</td><td>óxido de nitrógeno(V)</td><td>pentóxido de dinitrógeno</td></tr><tr><td>I₂O₇</td><td>óxido de yodo(VII)</td><td>heptóxido de diyodo</td></tr><tr><td>P₂O₃</td><td>óxido de fósforo(III)</td><td>trióxido de difósforo</td></tr></tbody></table><p>Para Lewis de CO₂: O=C=O y dos pares libres por O. En SO₂ hay estructuras de resonancia; para óxidos con varios átomos centrales, como la fórmula empírica P₂O₅, no fuerces un único átomo central ni enlaces P—P como regla general.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'hidruros-e-hidracidos','chapter',$cbc$6. Hidruros metálicos, hidrácidos y compuestos covalentes de H$cbc$,60,$cbc$<p><strong>Hidruro metálico:</strong> Mᵐ⁺ + m H⁻ → MHₘ. El H vale −1. LiH, CaH₂, AlH₃; FeH₂ y FeH₃ son hidruros de hierro(II) y hierro(III), CuH y CuH₂ son de cobre(I) y cobre(II). Lewis iónico: Ca²⁺ + 2 [H]⁻, cada H⁻ con dueto.</p><p><strong>Hidrácidos:</strong> H + ciertos no metales de los grupos 16/17, sin O. HCl(g) es cloruro de hidrógeno; HCl(ac) se llama ácido clorhídrico. H₂S puede nombrarse sulfuro de hidrógeno y, en disolución acuosa, ácido sulfhídrico.</p><p><strong>Otros hidruros covalentes:</strong> H₂O (agua), NH₃ (amoníaco), CH₄ (metano), SiH₄ (silano), PH₃ (fosfina), AsH₃ (arsina), BH₃ (borano). No clasifiques CH₄ como sal ni como hidruro metálico. Otros compuestos entre no metales, como SF₆ y PCl₅, se nombran por atomicidad.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'sales-binarias','chapter',$cbc$7. Sales binarias$cbc$,70,$cbc$<p>Metal + anión monoatómico no metálico. Primero el no metal terminado en <strong>-uro</strong>, luego «de metal» y Stock si corresponde. Es una red iónica: ajustá cargas y dibujá los iones separados para Lewis.</p><table><thead><tr><th>Fórmula</th><th>Iones</th><th>Nombre</th></tr></thead><tbody><tr><td>NaCl</td><td>Na⁺, Cl⁻</td><td>cloruro de sodio</td></tr><tr><td>CaF₂</td><td>Ca²⁺, 2 F⁻</td><td>fluoruro de calcio</td></tr><tr><td>Al₂S₃</td><td>2 Al³⁺, 3 S²⁻</td><td>sulfuro de aluminio</td></tr><tr><td>FeS / Fe₂S₃</td><td>Fe²⁺ / Fe³⁺</td><td>sulfuro de hierro(II) / hierro(III)</td></tr><tr><td>CuI / CuI₂</td><td>Cu⁺ / Cu²⁺</td><td>yoduro de cobre(I) / cobre(II)</td></tr></tbody></table><p>En Lewis del anión completá su octeto entre corchetes y colocá fuera la carga; verificá la suma total.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'hidroxidos','chapter',$cbc$8. Hidróxidos metálicos$cbc$,80,$cbc$<p>Metal + grupo OH⁻ (O = −2, H = +1). Fórmula M(OH)ₘ para metal de carga +m. Nombre: <strong>hidróxido de metal(Stock)</strong> si corresponde. KOH es hidróxido de potasio; Co(OH)₂ es hidróxido de cobalto(II); Ni(OH)₃ es hidróxido de níquel(III).</p><p>Lewis: dentro de [OH]⁻ hay enlace covalente O—H y tres pares libres en O; el catión metálico es una especie separada. Co(OH)₂ contiene Co²⁺ y dos [OH]⁻. Escribí paréntesis si hay más de un OH⁻: Ca(OH)₂, no CaOH₂.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'oxoacidos','chapter',$cbc$9. Oxoácidos y ácido fosfórico$cbc$,90,$cbc$<p>H + elemento central X + O; en esta guía se trabajan principalmente no metales. Generalmente H = +1 y O = −2; hallá X de la suma igual a cero. En Lewis X va al centro, los O alrededor y cada H enlazado a un O. H₂SO₃ se representa HO—S(=O)—OH (con par libre en S); HClO₄, HO—Cl(=O)₃ en la representación usual.</p><table><thead><tr><th>Serie</th><th>Estados y nombres</th></tr></thead><tbody><tr><td>Carbono</td><td>H₂CO₃: ácido carbónico (+4)</td></tr><tr><td>Nitrógeno</td><td>HNO₂: ácido nitroso (+3); HNO₃: ácido nítrico (+5)</td></tr><tr><td>Azufre</td><td>H₂SO₃: ácido sulfuroso (+4); H₂SO₄: ácido sulfúrico (+6)</td></tr><tr><td>Cloro</td><td>HClO: hipocloroso (+1); HClO₂: cloroso (+3); HClO₃: clórico (+5); HClO₄: perclórico (+7)</td></tr><tr><td>Fósforo</td><td>H₃PO₄: ácido fosfórico u ortofosfórico; excepción de tres H en esta secuencia</td></tr></tbody></table><p>En el conjunto simplificado de la cátedra, X de grupo impar suele dar un H y X de grupo par dos H; es una <strong>regla mnemotécnica limitada</strong>, no una ley general (H₃PO₄ es la excepción tratada). Para hallar O usá siempre la suma de oxidaciones.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'oxoaniones','chapter',$cbc$10. De oxoácido a oxoanión: sufijos y cargas$cbc$,100,$cbc$<p>Al retirar todos los H⁺ de un oxoácido queda un oxoanión. Cada protón retirado aporta una unidad de carga negativa al ion: H₂SO₄ → SO₄²⁻ + 2 H⁺; HClO₃ → ClO₃⁻ + H⁺. Los electrones no se eliminan junto con H⁺.</p><table><thead><tr><th>Ácido</th><th>Anión</th><th>Ejemplo</th></tr></thead><tbody><tr><td>hipo-…-oso</td><td>hipo-…-ito</td><td>HClO → ClO⁻, hipoclorito</td></tr><tr><td>…-oso</td><td>…-ito</td><td>HNO₂ → NO₂⁻, nitrito</td></tr><tr><td>…-ico</td><td>…-ato</td><td>HNO₃ → NO₃⁻, nitrato</td></tr><tr><td>per-…-ico</td><td>per-…-ato</td><td>HClO₄ → ClO₄⁻, perclorato</td></tr></tbody></table><p>También: CO₃²⁻ carbonato; SO₃²⁻ sulfito; SO₄²⁻ sulfato; ClO₂⁻ clorito; ClO₃⁻ clorato; PO₄³⁻ fosfato. Para SO₄²⁻: x + 4(−2) = −2, entonces x = +6. Para ClO₃⁻: x + 3(−2) = −1, entonces x = +5.</p><p>Lewis de oxoaniones: X central y O alrededor; electrones y cargas formales deben sumar la carga del ion. Dibujá entre corchetes, con resonancia cuando existan posiciones equivalentes (NO₃⁻, SO₄²⁻).</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'oxosales','chapter',$cbc$11. Oxosales y fosfatos$cbc$,110,$cbc$<p>Catión metálico + oxoanión: nombrá el anión y después «de metal» con Stock si es variable. NaNO₂ = nitrito de sodio; NaBrO₄ = perbromato de sodio; Na₃PO₄ = fosfato de sodio. Para el ion SeO₃²⁻ (Se +4), se usa selenito; con un catión metálico, balanceá antes de escribir la fórmula.</p><p>La fórmula debe conservar el oxoanión completo: Fe³⁺ + SO₄²⁻ → Fe₂(SO₄)₃. En Lewis de una oxosal mostrás cationes separados de los oxoaniones, cuya unión interna X—O es covalente. H₃PO₄ puede perder tres H⁺ y dar PO₄³⁻, que requiere tres Na⁺ en Na₃PO₄.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'hidrogenosales','chapter',$cbc$12. Hidrogenosales no oxigenadas$cbc$,120,$cbc$<p>También llamadas sales ácidas sin oxígeno. Parten de un hidrácido con más de un H: H₂S → HS⁻ → S²⁻ por pérdidas sucesivas de H⁺. La sal con HS⁻ conserva un hidrógeno: NaHS = <strong>hidrogenosulfuro de sodio</strong>. En cambio Na₂S = sulfuro de sodio.</p><p>La estructura es iónica entre Na⁺ y [HS]⁻, mientras H—S dentro del anión es covalente. Para formular, balanceá la carga del hidrógenoanión con la del catión; no confundas la cantidad de H remanente con la carga.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'hidrogeno-oxosales','chapter',$cbc$13. Hidrógeno-oxosales y fosfatos ácidos$cbc$,130,$cbc$<p>Catión + hidrógeno-oxoanión; contienen metal, H, X y O. H₂SO₄ → HSO₄⁻ → SO₄²⁻. KHSO₄ = hidrogenosulfato de potasio. H₂CO₃ → HCO₃⁻ → CO₃²⁻; NaHCO₃ = hidrogenocarbonato de sodio (nombre usual: bicarbonato).</p><p>H₃PO₄ pierde H⁺ en tres etapas: H₂PO₄⁻ (dihidrogenofosfato), HPO₄²⁻ (hidrogenofosfato) y PO₄³⁻ (fosfato). Ejemplos: NaH₂PO₄, Na₂HPO₄ y Na₃PO₄. Los subíndices de Na cambian para neutralizar las cargas −1, −2 y −3.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'sales-amonio','chapter',$cbc$14. Sales de amonio: tres familias$cbc$,140,$cbc$<p>NH₄⁺ es el <strong>catión amonio</strong>, aunque no contiene metal. Puede pensarse como NH₃ + H⁺; en Lewis el par libre del N participa en la unión con H⁺, y el ion final tiene cuatro enlaces N—H equivalentes y carga +1. Estados formales de oxidación: N −3, H +1.</p><table><thead><tr><th>Tipo</th><th>Fórmula</th><th>Nombre</th></tr></thead><tbody><tr><td>Anión monoatómico</td><td>NH₄Cl; (NH₄)₂S</td><td>cloruro de amonio; sulfuro de amonio</td></tr><tr><td>Oxoanión</td><td>NH₄NO₃; (NH₄)₂SO₄</td><td>nitrato de amonio; sulfato de amonio</td></tr><tr><td>Hidrógeno-oxoanión</td><td>NH₄HSO₄</td><td>hidrogenosulfato de amonio</td></tr></tbody></table><p>Usá paréntesis si se repite NH₄⁺; por ejemplo, dos cationes equilibran S²⁻ o SO₄²⁻. No trates NH₄⁺ como un único átomo metálico.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'lewis-por-familia','chapter',$cbc$15. Lewis: qué se dibuja en cada familia$cbc$,150,$cbc$<p><strong>Compuesto iónico:</strong> dibujá catión(es) y anión(es) separados, cada ion con carga. En aniones poliatómicos hay enlaces covalentes internos: [OH]⁻, [NO₂]⁻, [HSO₄]⁻. Comprobá que la suma de cargas sea cero.</p><p><strong>Molécula covalente:</strong> contá electrones de valencia; elegí átomo central; dibujá enlaces, pares libres y, si corresponde, dobles enlaces, resonancia o cargas formales. En oxoácidos el H va unido a O; en CH₄ hay cuatro enlaces C—H. Para iones usá corchetes y carga.</p><p>El dibujo de enlaces dativos usado en algunas diapositivas es una forma didáctica de llevar pares; no significa que un enlace N—H de NH₄⁺ sea físicamente distinto de los otros tres. Para estructuras de S, P o Cl pueden encontrarse convenciones de Lewis alternativas: verificá siempre electrones totales y cargas.</p>$cbc$,false);
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',5,'cuadro-integrador','chapter',$cbc$16. Cuadro final de nombres y trampas frecuentes$cbc$,160,$cbc$<table><thead><tr><th>Señal</th><th>Familia</th><th>Terminación o nombre</th><th>Error a evitar</th></tr></thead><tbody><tr><td>Metal + O</td><td>óxido básico</td><td>óxido de…</td><td>olvidar simplificar</td></tr><tr><td>No metal + O</td><td>óxido covalente</td><td>Stock o prefijos</td><td>dibujarlo como iones</td></tr><tr><td>Metal + H</td><td>hidruro</td><td>hidruro de…</td><td>poner H = +1</td></tr><tr><td>Metal + X</td><td>sal binaria</td><td>…uro de…</td><td>olvidar Stock</td></tr><tr><td>OH⁻</td><td>hidróxido</td><td>hidróxido de…</td><td>omitir paréntesis</td></tr><tr><td>H + X + O</td><td>oxoácido</td><td>…oso / …ico</td><td>unir H al centro</td></tr><tr><td>Metal + XOᵧ</td><td>oxosal</td><td>…ito / …ato de…</td><td>romper el oxoanión</td></tr><tr><td>Metal + HX</td><td>hidrogenosal</td><td>hidrógeno…uro</td><td>confundir con hidrácido</td></tr><tr><td>Metal + HXOᵧ</td><td>hidrógeno-oxosal</td><td>hidrógeno…ito/ato</td><td>quitar todos los H</td></tr><tr><td>NH₄⁺</td><td>sal de amonio</td><td>… de amonio</td><td>buscar un metal</td></tr></tbody></table><p><strong>Control de examen:</strong> clasificación → estados de oxidación → iones o molécula → fórmula/nombre → Lewis → suma de cargas y electrones. Una reacción de neutralización completa produce sal y agua; la neutralización parcial puede dejar H en una sal ácida.</p>$cbc$,false);
