-- Unidad 5: nomenclatura y formulación. Contenido basado en los ocho archivos entregados.
-- Migración idempotente: sólo reemplaza el contenido de la Unidad 5.
begin;
delete from public.exercise_solutions where exercise_id in (select id from public.exercises where subject='chemistry' and unit_no=5);
delete from public.exercises where subject='chemistry' and unit_no=5;
delete from public.course_sections where subject='chemistry' and unit_no=5;
with inserted as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'practica-integrada',$cbc$Problema resuelto · ocho sustancias$cbc$,$cbc$<p>Dadas las siguientes sustancias: a) H₂SO₃; b) HClO₄; c) Ni(OH)₃; d) NaNO₂; e) Cu₂S; f) CH₄; g) CaH₂; h) SO₂.</p><ol type="i"><li>Clasificarlas en binarias o ternarias.</li><li>Decir a qué familia pertenecen, si son mayormente iónicas o covalentes, y nombrarlas.</li><li>Escribir en cada caso la estructura de Lewis.</li></ol>$cbc$,'Química CBC · Cátedra Di Risio, Uniones-Nomenclatura-Lewis',10,false) returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p><strong>i)</strong> Binarios: e, f, g, h. Ternarios: a, b, c, d.</p><div class="solutionStep"><span>A</span><div><h4>H₂SO₃ · ácido sulfuroso</h4><p>ternario · oxoácido · covalente.</p><p><strong>Oxidación:</strong> 2(+1)+x+3(−2)=0 → x(S)=+4.</p><p><strong>Lewis:</strong> HO—S(=O)—OH; el S conserva un par libre y cada H se une a O.</p></div></div><div class="solutionStep"><span>B</span><div><h4>HClO₄ · ácido perclórico</h4><p>ternario · oxoácido · covalente.</p><p><strong>Oxidación:</strong> (+1)+x+4(−2)=0 → x(Cl)=+7.</p><p><strong>Lewis:</strong> HO—Cl(=O)₃ es la forma de Lewis usual; H unido a O.</p></div></div><div class="solutionStep"><span>C</span><div><h4>Ni(OH)₃ · hidróxido de níquel(III)</h4><p>ternario · hidróxido · iónico.</p><p><strong>Oxidación:</strong> x+3(−1)=0 → x(Ni)=+3.</p><p><strong>Lewis:</strong> Ni³⁺ y 3 [OH]⁻; cada O—H es covalente dentro del ion.</p></div></div><div class="solutionStep"><span>D</span><div><h4>NaNO₂ · nitrito de sodio</h4><p>ternario · oxosal · iónico.</p><p><strong>Oxidación:</strong> Na⁺ y NO₂⁻; x(N)+2(−2)=−1 → x(N)=+3.</p><p><strong>Lewis:</strong> Na⁺ y [NO₂]⁻; N central, un enlace N=O y otro N—O⁻, dos formas resonantes.</p></div></div><div class="solutionStep"><span>E</span><div><h4>Cu₂S · sulfuro de cobre(I)</h4><p>binario · sal binaria · iónico.</p><p><strong>Oxidación:</strong> 2x+(−2)=0 → x(Cu)=+1.</p><p><strong>Lewis:</strong> 2 Cu⁺ y [S]²⁻ con octeto.</p></div></div><div class="solutionStep"><span>F</span><div><h4>CH₄ · metano</h4><p>binario · hidruro covalente · covalente.</p><p><strong>Oxidación:</strong> C y H son no metales; 4 enlaces C—H.</p><p><strong>Lewis:</strong> C central con cuatro enlaces simples C—H; sin pares libres en C.</p></div></div><div class="solutionStep"><span>G</span><div><h4>CaH₂ · hidruro de calcio</h4><p>binario · hidruro metálico · iónico.</p><p><strong>Oxidación:</strong> x+2(−1)=0 → x(Ca)=+2.</p><p><strong>Lewis:</strong> Ca²⁺ y 2 [H]⁻; cada H⁻ completa dueto.</p></div></div><div class="solutionStep"><span>H</span><div><h4>SO₂ · dióxido de azufre u óxido de azufre(IV)</h4><p>binario · óxido no metálico · covalente.</p><p><strong>Oxidación:</strong> x+2(−2)=0 → x(S)=+4.</p><p><strong>Lewis:</strong> O—S—O con dos enlaces equivalentes por resonancia; también suele dibujarse O=S=O.</p></div></div>$cbc$,'e–h binarias; a–d ternarias. Ver familia, nombre y Lewis por sustancia.',true from inserted;
commit;
